<script setup lang="ts">
import { computed,ref,onMounted } from 'vue'
import { api,bootstrap,ApiError,notify } from '../composables/api'
import { date } from '../composables/investigation'
import { useCollaborationAction,noteDirty } from '../composables/collaboration'
import { noteParts } from '../composables/noteLinks'
import type { NoteDraft,NoteItem,NotesResult } from '../types'
const props=defineProps<{issue:string;draft:NoteDraft}>(),emit=defineEmits<{changed:[]}>(),notes=ref<NotesResult|null>(null),loading=ref(false),saving=ref(false),error=ref(''),conflict=ref(false),confirmDelete=ref<string|null>(null)
const perform=useCollaborationAction(),length=computed(()=>Array.from(props.draft.body).length)
async function load(){loading.value=true;try{notes.value=await api<NotesResult>('/issues/'+props.issue+'/notes?page='+props.draft.page)}catch(e){error.value=e instanceof Error?e.message:'Notes could not be loaded.'}finally{loading.value=false}}
onMounted(load)
function reset(){Object.assign(props.draft,{body:'',baseline:'',id:null,version:0});conflict.value=false;error.value=''}
function cancel(){if(noteDirty(props.draft)&&!window.confirm('Discard your unsaved note draft?'))return;reset()}
function edit(n:NoteItem){if(noteDirty(props.draft)&&!window.confirm('Discard your current draft and edit this note?'))return;Object.assign(props.draft,{id:n.id,version:n.version,body:n.body??'',baseline:n.body??''});error.value='';conflict.value=false}
async function save(){if(!props.draft.body.trim()||length.value>10000){error.value='Enter 1–10,000 characters.';return}saving.value=true;error.value='';const editing=props.draft.id
 try{await perform('/issues/'+props.issue+'/notes'+(editing?'/'+editing:''),editing?'PATCH':'POST',{...(editing?{version:props.draft.version}:{}),exception_monitor_private:{body:props.draft.body}});if(!editing)props.draft.page=1;reset();notify(editing?'Note updated.':'Note added.');emit('changed')}
 catch(e){error.value=e instanceof Error?e.message:'The note could not be saved.';conflict.value=e instanceof ApiError&&e.status===409}finally{saving.value=false}}
async function remove(n:NoteItem){saving.value=true;error.value='';try{await perform('/issues/'+props.issue+'/notes/'+n.id,'DELETE',{version:n.version});confirmDelete.value=null;if(props.draft.id===n.id)reset();notify('Note text removed. A metadata tombstone remains.');emit('changed')}catch(e){error.value=e instanceof Error?e.message:'The note could not be removed.'}finally{saving.value=false}}
async function latest(){if(noteDirty(props.draft)&&!window.confirm('Discard your draft and load the latest note text?'))return;await load();const n=notes.value?.items.find(n=>n.id===props.draft.id);if(n&&n.state!=='deleted'){Object.assign(props.draft,{id:n.id,version:n.version,body:n.body??'',baseline:n.body??''});conflict.value=false;error.value=''}else{error.value='This note was removed or is on another page. Your draft remains available to copy.'}}
function asNew(){props.draft.id=null;props.draft.version=0;props.draft.baseline='';conflict.value=false}
async function page(n:number){props.draft.page=n;await load()}
</script>
<template><section class="notes-section"><div class="section-heading"><h3>Investigation notes</h3><small v-if="notes">{{notes.total}} {{notes.total==='1'?'note':'notes'}}</small></div><p class="help">Notes belong to this error across all occurrences and are visible to authorized dashboard users. Plain text; no attachments or mentions. Note text is never included in notification payloads.</p><div v-if="error" class="notice danger" role="alert"><div><p>{{error}}</p><div v-if="conflict" class="inline-actions"><button class="button" @click="latest">Load latest note</button><button v-if="draft.id" class="button" @click="asNew">Use draft as new note</button></div><button v-else-if="!notes" class="button" @click="load">Try again</button></div></div><form v-if="bootstrap?.capabilities.operate" class="note-composer" @submit.prevent="save"><label class="field">{{draft.id?'Edit your note':'Add an investigation note'}}<textarea v-model="draft.body" :disabled="saving" rows="5" aria-describedby="note-draft-help" placeholder="What did you discover? Include steps or a runbook link."></textarea></label><div id="note-draft-help" class="note-composer-help"><span>{{length.toLocaleString()}} / 10,000 characters · privacy redaction applies</span><span v-if="noteDirty(draft)">Unsaved draft</span></div><div class="inline-actions"><button class="button primary" :disabled="saving||!draft.body.trim()||length>10000">{{saving?'Saving…':draft.id?'Save note changes':'Add note'}}</button><button v-if="draft.id||draft.body" class="button" type="button" :disabled="saving" @click="cancel">{{draft.id?'Cancel edit':'Discard draft'}}</button></div></form><p v-if="loading" role="status" class="help">Loading notes…</p><div v-if="notes" class="note-list"><article v-for="n in notes.items" :key="n.id" class="note-entry"><header><strong>{{n.author}}</strong><time>{{date(n.created_at)}}</time><span v-if="n.edited_at" class="help">Edited {{date(n.edited_at)}}</span></header><p v-if="n.state==='deleted'" class="help">Note text removed {{date(n.deleted_at)}}. Activity retains metadata only.</p><p v-else-if="n.state==='unreadable'" class="notice neutral">The retained note text could not be decrypted. Review host encryption-key availability.</p><p v-else class="note-body"><template v-for="(part,index) in noteParts(n.body??'')" :key="index"><a v-if="part.href" :href="part.href" target="_blank" rel="noopener noreferrer">{{part.text}}</a><template v-else>{{part.text}}</template></template></p><div class="inline-actions"><button v-if="n.can_edit" class="text-link" :disabled="saving" @click="edit(n)">{{n.state==='unreadable'?'Replace note text':'Edit'}}</button><button v-if="n.can_delete" class="text-link danger-link" :disabled="saving" @click="confirmDelete=n.id">Delete</button></div><div v-if="confirmDelete===n.id" class="notice warning"><div><p>Delete this note text? Its body will be removed; a metadata tombstone remains. An open draft of this same note will also be discarded.</p><div class="inline-actions"><button class="button" :disabled="saving" @click="remove(n)">Confirm delete note</button><button class="button" :disabled="saving" @click="confirmDelete=null">Keep note</button></div></div></div></article><p v-if="!notes.items.length" class="help">No investigation notes yet.</p><div class="pagination"><span>Page {{notes.page}} of {{notes.last_page}}</span><button class="button" :disabled="loading||notes.page<=1" @click="page(notes.page-1)">Previous notes</button><button class="button" :disabled="loading||notes.page>=notes.last_page" @click="page(notes.page+1)">Next notes</button></div></div></section></template>
